import { useMemo, forwardRef } from 'react'
import { CustomText, InnerForm } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { getVehicleDataForm } from '../../constants'

function OfflineVehicleData ({ protectionType, preFilledData, isRequired }, ref) {
  const vehicleFormData = useMemo(() => {
    return getVehicleDataForm({ ...preFilledData }, protectionType, isRequired)
  }, [protectionType, preFilledData, isRequired])
  return (
    <>
      <CustomText
        color={AgentColorPallette.black}
        weight={800}
        size='16px'
        top='20px'
        bottom='10px'
      >
        {LANG_STRINGS.vehicleData}
      </CustomText>
      <InnerForm
        formData={vehicleFormData}
        isReturnError
        ref={ref}
      />
    </>
  )
}

export default forwardRef(OfflineVehicleData)
