import { useMemo, forwardRef, useState, useCallback } from 'react'
import { CustomText, InnerForm } from '../../../../../components'
import ImageGuideModal from '../../../../../components/PolicyCustAgentForm/components/ImageGuideModal'
import SingleImgContainer from '../../../../../components/SingleImgContainer'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { CERTIFICATE_PREVIEW, STNK } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { getPolicyVehicleAttachments, getFleetVehicleDocuments, getAdditionalInfoAttachments } from '../../constants'
import { PolicyAttachmentStyle } from './index.style'

function PolicyAttachments ({ isManualPolicy, protectionType, preFilledData, isAdditionalInfo }, ref) {
  const attachmentData = useMemo(() => {
    if (isAdditionalInfo) {
      return getAdditionalInfoAttachments({ ...preFilledData }, protectionType, isManualPolicy)
    }
    return isManualPolicy ? getPolicyVehicleAttachments({ ...preFilledData }, protectionType)
      : getFleetVehicleDocuments({ ...preFilledData }, protectionType)
  }, [isManualPolicy, protectionType, preFilledData, isAdditionalInfo])
  const [showImgModal, setShowImgModal] = useState({})

  const handleShowImgContainer = useCallback((item) => {
    let title = ''
    let btmTitle = ''
    let imgTitle = ''
    let imgGuide = ''
    if (item.name === 'previous_certificate_url') {
      title = LANG_STRINGS.certificatePolicyGuide
      btmTitle = LANG_STRINGS.verifyThePolicyCertificate
      imgTitle = item.placeholder
      imgGuide = CERTIFICATE_PREVIEW
    } else if (item.name === 'stnk_url') {
      title = LANG_STRINGS.stnkPhotoGuide
      btmTitle = LANG_STRINGS.makeSureVehicleRegistrationPicClear
      imgGuide = STNK
      imgTitle = item.label
    }
    setShowImgModal({
      show: true,
      title,
      imgContainer: (
        <SingleImgContainer
          title={imgTitle}
          imgUrl={imgGuide}
          titlePosition='up'
          titleAlign='start'
        />
      ),
      btmTitle
    })
  }, [])

  const handleCloseImgModal = useCallback(() => {
    setShowImgModal({
      show: false
    })
  }, [])

  return (
    <PolicyAttachmentStyle>
      <CustomText
        color={AgentColorPallette.black}
        weight={800}
        size='16px'
        bottom='10px'
      >
        {LANG_STRINGS.attachment}
      </CustomText>
      <InnerForm
        formData={attachmentData}
        ref={ref}
        onGuideClick={handleShowImgContainer}
      />
      {
        showImgModal.show && (
          <ImageGuideModal
            showImgModal={showImgModal.show}
            title={showImgModal.title}
            onClose={handleCloseImgModal}
            modalImgContainer={showImgModal.imgContainer}
            bottomTitle={showImgModal.btmTitle}
          />
        )
      }
    </PolicyAttachmentStyle>
  )
}

export default forwardRef(PolicyAttachments)
