import { useCallback, useState } from 'react'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText, Upload } from '../../../../../components'
import ImageGuideModal from '../../../../../components/PolicyCustAgentForm/components/ImageGuideModal'
import TitleError from '../../../../../components/TitleError'
import VehicleGuideImgs from '../../../../../components/VehicleGuideImgs'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { PolicyVehicleImgsStyle } from './index.style'

function PolicyVehicleImgs ({ images = {}, errorImages = {}, isVehicleImgRequired, onUpdateVehicleImg = () => {} }) {
  const [showImgModal, setShowImgModal] = useState({

  })

  const handleShowImgContainer = useCallback(() => {
    setShowImgModal({
      show: true,
      title: LANG_STRINGS.vehiclePhotoGuide,
      btmTitle: LANG_STRINGS.makeSureCarPicClear
    })
  }, [])

  const handleCloseImgModal = useCallback(() => {
    setShowImgModal({
      show: false
    })
  }, [])

  const getRowImageContainer = useCallback(({
    title, img, type, errorImages,
    width, labelAlign, className
  }) => {
    return (
      <div className={className}>
        <TitleError
          title={title}
          error={errorImages[type] ? LANG_STRINGS.required : ''}
          required={isVehicleImgRequired}
        />
        <Upload
          hideLabel
          displayBorder
          className='upload-wrapper box-shadow'
          label={title}
          width={width}
          name={type}
          labelAlign={labelAlign}
          defaultValue={img}
          showImg
          onUpload={(data) => onUpdateVehicleImg(data, 'images', type)}
          errorField={errorImages[type] && !img && type}
        />
      </div>
    )
  }, [onUpdateVehicleImg, isVehicleImgRequired])

  return (
    <PolicyVehicleImgsStyle>
      <Row align='center' justify='space-between'>
        <CustomText
          color={AgentColorPallette.black}
          weight={800}
          size='16px'
          bottom='10px'
        >
          {LANG_STRINGS.vehiclePhoto}
        </CustomText>
        <CustomText
          color={AgentColorPallette.darkerGold}
          weight={700}
          onClick={handleShowImgContainer}
        >
          {LANG_STRINGS.guide}
        </CustomText>
      </Row>
      {
        getRowImageContainer({
          title: LANG_STRINGS.dashboard,
          img: images.dashboard,
          type: 'dashboard',
          errorImages
        })
      }
      <Row justify='space-between' align='center'>
        {
          getRowImageContainer({
            title: LANG_STRINGS.frontLook,
            img: images.front,
            type: 'front',
            errorImages,
            width: '100%',
            className: 'small-img-wrapper'
          })
        }
        {
          getRowImageContainer({
            title: LANG_STRINGS.backView,
            img: images.back,
            type: 'back',
            errorImages,
            width: '100%',
            className: 'small-img-wrapper'
          })
        }
      </Row>
      <Row justify='space-between' align='center'>
        {
          getRowImageContainer({
            title: LANG_STRINGS.leftSide,
            img: images.left,
            type: 'left',
            errorImages,
            width: '100%',
            className: 'small-img-wrapper'
          })
        }
        {
          getRowImageContainer({
            title: LANG_STRINGS.toTheRightSide,
            img: images.right,
            type: 'right',
            errorImages,
            width: '100%',
            className: 'small-img-wrapper'
          })
        }
      </Row>
      {
        showImgModal.show && (
          <ImageGuideModal
            showImgModal={showImgModal.show}
            title={showImgModal.title}
            onClose={handleCloseImgModal}
            modalImgContainer={(
              <VehicleGuideImgs />
            )}
            bottomTitle={showImgModal.btmTitle}
          />
        )
      }
    </PolicyVehicleImgsStyle>
  )
}

export default PolicyVehicleImgs
