import { useMemo, forwardRef, useCallback, useState } from 'react'
import { CustomText, InnerForm } from '../../../../../components'
import AddressForm from '../../../../../components/AddressForm'
import ImageGuideModal from '../../../../../components/PolicyCustAgentForm/components/ImageGuideModal'
import SingleImgContainer from '../../../../../components/SingleImgContainer'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { KTP_IMG } from '../../../../../images'
import { LANG_STRINGS } from '../../../../../lang'
import { getCustomerData } from '../../constants'
import { PolicyHolderStyle } from './index.style'

function PolicyHolderData (
  {
    isManualPolicy, protectionType, preFilledData = {},
    getProvinceCityData = () => {}, onCustomerAddressChange = () => {},
    onCustomerFormChange = () => {}
  }, ref
) {
  const customerData = useMemo(() => {
    return getCustomerData(preFilledData, isManualPolicy, protectionType)
  }, [isManualPolicy, protectionType, preFilledData])
  const [showImgModal, setShowImgModal] = useState({})

  const handleShowImgContainer = useCallback((type) => {
    let title = ''
    let btmTitle = ''
    let imgContainer = ''
    if (type === 'npwp_url') {

    } else {
      title = LANG_STRINGS.ktpPhotoGuide
      btmTitle = LANG_STRINGS.makeSureKTPPhotoClear
      imgContainer = (
        <SingleImgContainer
          title={LANG_STRINGS.photoKTP}
          imgUrl={KTP_IMG}
          titlePosition='up'
          titleAlign='start'
        />
      )
    }
    setShowImgModal({
      show: true,
      title,
      imgContainer,
      btmTitle
    })
  }, [])

  const handleCloseImgModal = useCallback(() => {
    setShowImgModal({
      show: false
    })
  }, [])

  return (
    <PolicyHolderStyle>
      <CustomText
        color={AgentColorPallette.black}
        weight={800}
        size='16px'
        bottom='10px'
      >
        {LANG_STRINGS.policyHolderNew}
      </CustomText>
      <InnerForm
        formData={customerData}
        onInputChange={onCustomerFormChange}
        onGuideClick={() => handleShowImgContainer(LANG_STRINGS.photoKTP, 'ktp_url')}
        ref={ref}
      />
      <AddressForm
        handleGetAddressSubmit={getProvinceCityData}
        address={preFilledData?.customer_address}
        onAddressChange={onCustomerAddressChange}
        labels={{
          province: LANG_STRINGS.province,
          city: LANG_STRINGS.city
        }}
      />
      {
        showImgModal.show && (
          <ImageGuideModal
            showImgModal={showImgModal.show}
            title={showImgModal.title}
            onClose={handleCloseImgModal}
            modalImgContainer={showImgModal.imgContainer}
            bottomTitle={showImgModal.btmTitle}
          />
        )
      }
    </PolicyHolderStyle>
  )
}

export default forwardRef(PolicyHolderData)
