import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Container, CustomText } from '../../../../../../components'
import StepsHeader from '../../../../../../components/StepsHeader'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import { MANUAL_ORDER } from '../../../../../../constants/pkgCode'
import { SEND_GOLD_ICON } from '../../../../../../images'
import { LANG_STRINGS } from '../../../../../../lang'
import OfflineVehicleData from '../../../components/OfflineVehicleData'
import PolicyAttachments from '../../../components/PolicyAttachments'
import PolicyVehicleImgs from '../../../components/PolicyVehicleImg'
import PolicyHolderData from '../../../components/PolicyHolderData'
import { OfflinePolicyFormSection, OfflinePolicyFormStyle } from './index.style'
import { clearLocalStorage, getFromLocalStorageData, setToLocalStorage } from '../../../../../../helpers/localstorage'
import { OFFLINE_FORM_DATA } from '../../../../../../constants/cookies'
// import { NEW_POLICY_USED_CAR, RENEW_POLICY_WITH_DIFFERENT_PROVIDER, RENEW_POLICY_WITH_SAME_PROVIDER } from '../../../constants'
import HardCopySection from '../../../../../../components/HardCopySection'
import { useSaveCustomerData } from '../../../../../../state/globalState/hooks/useGlobalContext'
import { useUpdateOfflineQuote } from '../../../state/hooks/usePolicyState'
import { getOfflineStepTwoReqBody } from '../../../../../../helpers/getPackageBody'
import { resetError, updateLoader, useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import ShowSnackbar from '../../../../../../components/ShowNotification'
import BottomBtn from '../../../../../../components/BottomBtn'

function OfflinePolicyDetailsFormContainer ({ match, history, location }) {
  const urlParams = useMemo(() => match?.params || {}, [match])
  const [errorImages, setErrorImages] = useState({})
  const isEditPage = useMemo(() => (urlParams.quoteId && location.pathname.includes('edit')), [urlParams, location])
  // this field returns the data of first steps
  const offlineLocalData = useRef(getFromLocalStorageData(OFFLINE_FORM_DATA))
  // we get the type of protection in different variables
  const protectionType = useRef(offlineLocalData.current.protection_type || {})
  // const isShowVehicleImgContainer = useMemo(() => {
  //   return [NEW_POLICY_USED_CAR, RENEW_POLICY_WITH_DIFFERENT_PROVIDER, RENEW_POLICY_WITH_SAME_PROVIDER].includes(protectionType.current.code)
  // }, [protectionType])
  const isVehicleImgRequired = true // protectionType.current.code !== NEW_POLICY_NEW_CAR
  const savedCustomerDataToGlobalStore = useSaveCustomerData()
  const isManualPolicy = useMemo(() => urlParams.purchaseType === MANUAL_ORDER, [urlParams.purchaseType])
  const imagesRef = useRef({})
  const policyAttachmentRef = useRef(null)
  const vehicleDataRef = useRef(null)
  const policyHolderDataRef = useRef(null)
  const provinceCityRef = useRef(null)
  const that = useRef({
    isGlobalStoreUpdated: false
  })
  const [, updateOfflineQuoteReq] = useUpdateOfflineQuote()
  const [{ UPDATE_OFFLINE_QUOTE_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [{ updateOfflineQuoteStatus }, dispatchError] = useErrorContextValue()

  useEffect(() => {
    // save customer data from pre filled Data
    if (!that.current.isGlobalStoreUpdated) {
      that.current.isGlobalStoreUpdated = true
      savedCustomerDataToGlobalStore({
        customer_name: offlineLocalData.current?.customer_name,
        mobile_no: offlineLocalData.current?.mobile_no,
        customer_address: offlineLocalData.current?.customer_address
      })
    }
  }, [savedCustomerDataToGlobalStore])

  useEffect(() => {
    function resetErrorKey (key) {
      dispatchError(resetError({
        [key]: undefined
      }))
    }

    if (updateOfflineQuoteStatus === 'success') {
      history.goBack()
      clearLocalStorage()
      resetErrorKey('updateOfflineQuoteStatus')
    } else if (updateOfflineQuoteStatus) {
      ShowSnackbar.error({
        visible: true,
        text: updateOfflineQuoteStatus
      })
      resetErrorKey('updateOfflineQuoteStatus')
    }
  }, [history, dispatchError, updateOfflineQuoteStatus])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        UPDATE_OFFLINE_QUOTE_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handlingVehicleImgs = useCallback((data, type, name) => {
    imagesRef.current = {
      [type]: {
        ...imagesRef.current[type],
        ...data
      }
    }
    setErrorImages(oldError => {
      delete oldError[name]
      return {
        ...oldError
      }
    })
  }, [])

  const handleGetProvinceCity = useCallback((addressType, submitHandler) => {
    provinceCityRef.current = submitHandler
  }, [])

  const handleCustomerAddressChange = useCallback((customerAddress) => {
    savedCustomerDataToGlobalStore({
      customer_address: customerAddress
    })
  }, [savedCustomerDataToGlobalStore])

  const handleCustomerFormChange = useCallback((value, name) => {
    savedCustomerDataToGlobalStore({
      [name]: value
    })
  }, [savedCustomerDataToGlobalStore])

  const handleToChooseInsurance = useCallback(async (e) => {
    // here we are handling the cases for all the cases new, renew and renew from other
    let body = {}
    const attachmentData = await policyAttachmentRef.current.handleSubmit(e)
    const policyHolderData = await policyHolderDataRef.current.handleSubmit(e)
    const customerAddressData = await provinceCityRef.current(e)
    const hardCopyData = await HardCopySection.getHardCopyData(e)
    let isValidHardCopy = true
    let isValidImages = !isManualPolicy
    if (hardCopyData.hard_copy_required && !hardCopyData.isValid) {
      isValidHardCopy = false
    }
    if (isManualPolicy) {
      const vehicleData = await vehicleDataRef.current.handleSubmit(e) || {}
      if (vehicleData.error) return
      body = {
        ...vehicleData
      }
    }

    if (!isValidImages) {
      // check the valid images
      const { images = {} } = imagesRef.current
      const imgReq = ['dashboard', 'front', 'back', 'right', 'left']
      isValidImages = true
      const error = {}
      imgReq.forEach(item => {
        isValidImages = isValidImages && !!images[item]
        if (!images[item]) {
          error[item] = item
        }
      })
      setErrorImages(error)
    }

    if (attachmentData && policyHolderData && isValidHardCopy && isValidImages && customerAddressData) {
      body = {
        ...body,
        ...attachmentData,
        ...policyHolderData,
        ...imagesRef.current,
        ...hardCopyData,
        customer_address: {
          ...customerAddressData
        }
      }
      const storageData = {
        ...offlineLocalData.current,
        ...body
      }
      setToLocalStorage(OFFLINE_FORM_DATA, storageData)
      if (isEditPage) {
        if (urlParams.quoteId !== 'normal') {
          return updateOfflineQuoteReq({
            id: urlParams.quoteId,
            body: getOfflineStepTwoReqBody(storageData)
          })
        }

        return history.push({
          pathname: `/${urlParams.productCode}/${urlParams.purchaseType}/offline/review`,
          state: {
            productCode: urlParams.productCode,
            purchaseType: urlParams.purchaseType
          }
        })
      }
      history.push({
        pathname: `/${urlParams.productCode}/${urlParams.purchaseType}/offline/review`
      })
    }
  }, [
    urlParams, history, isManualPolicy, isEditPage,
    updateOfflineQuoteReq
  ])

  return (
    <Container
      title={urlParams.purchaseType === MANUAL_ORDER ? LANG_STRINGS.mobilManualOrder : `Mobil: ${LANG_STRINGS.fleet}`}
      hideBottomTabs
      loader={UPDATE_OFFLINE_QUOTE_LOADER}
      backBtnId='mobilManualOrderStepBack_2'
    >

      <OfflinePolicyFormStyle>
        {
          !isEditPage && (
            <StepsHeader
              className='application-steps-header'
              leftText={LANG_STRINGS.insuredObject}
              current='2'
              totalSteps='3'
            />
          )
        }
        <OfflinePolicyFormSection padBtm='0px'>
          <CustomText
            color={AgentColorPallette.darkCharcoal}
            size='13px'
            weight={700}
          >
            {LANG_STRINGS.completeTheFormToPolicyCreated}
          </CustomText>
          {
            isManualPolicy && (
              <OfflineVehicleData
                preFilledData={offlineLocalData.current}
                protectionType={protectionType.current.code}
                ref={vehicleDataRef}
              />
            )
          }
        </OfflinePolicyFormSection>
        {
          (isManualPolicy) && (
            <>
              <div className='separator' />
              <OfflinePolicyFormSection padding='0px'>
                <PolicyVehicleImgs
                  isVehicleImgRequired={isVehicleImgRequired}
                  onUpdateVehicleImg={handlingVehicleImgs}
                  images={offlineLocalData.current.images}
                  preFilledData={offlineLocalData.current}
                  errorImages={errorImages}
                />
              </OfflinePolicyFormSection>
              <div className='separator' />
            </>
          )
        }
        <OfflinePolicyFormSection padding='0px'>
          <PolicyAttachments
            isManualPolicy={isManualPolicy}
            protectionType={protectionType.current.code}
            preFilledData={offlineLocalData.current}
            ref={policyAttachmentRef}
          />
        </OfflinePolicyFormSection>
        <div className='separator' />
        <OfflinePolicyFormSection>
          <PolicyHolderData
            isManualPolicy={isManualPolicy}
            protectionType={protectionType.current.code}
            ref={policyHolderDataRef}
            preFilledData={offlineLocalData.current}
            getProvinceCityData={handleGetProvinceCity}
            onCustomerAddressChange={handleCustomerAddressChange}
            onCustomerFormChange={handleCustomerFormChange}
          />
        </OfflinePolicyFormSection>
        <div className='separator' />
        <OfflinePolicyFormSection padBtm='26%'>
          <HardCopySection
            preFilledData={offlineLocalData.current}
          />
        </OfflinePolicyFormSection>
        <BottomBtn
          title={isEditPage ? LANG_STRINGS.save : LANG_STRINGS.review}
          icon={SEND_GOLD_ICON}
          iconRight
          onClick={handleToChooseInsurance}
        />
      </OfflinePolicyFormStyle>
      <ShowSnackbar />
    </Container>
  )
}

export default OfflinePolicyDetailsFormContainer
